# PDF links and summaries for each paper, keyed by DOI.
# PDFs: open-access publisher versions, accepted manuscripts in NTU's DR-NTU repository, or SSRN versions.
# Each URL was checked on 14 Nov 2026: DR-NTU files returned a PDF from this exact URL; SSRN IDs were matched to the paper in Crossref.
# "one" and "summary" are written only from each paper's abstract (as published or as deposited in DR-NTU)
# and, where the full PDF was available, its text. Nothing is inferred from titles.

def ssrn(n): return f"https://papers.ssrn.com/sol3/Delivery.cfm?abstractid={n}"
def drntu(u): return f"https://dr.ntu.edu.sg/server/api/core/bitstreams/{u}/content"

PUB_OA = "Published version, open access"
AAM = "Accepted manuscript, DR-NTU repository"
SSRN_V = "Working-paper version, SSRN"

